CREATE OR REPLACE FUNCTION public.required_escalation_clarification_tx(p_conversation_id uuid, p_source_message_id uuid, p_escalation_rule text, p_clarification_content text, p_reason_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_conv record;v_existing record;v_clarification text;v_reason text;v_message_id uuid;v_prior_count integer;BEGIN IF p_conversation_id IS NULL OR p_source_message_id IS NULL THEN RETURN jsonb_build_object('result','invalid_input');END IF;IF p_escalation_rule IS DISTINCT FROM 'R2' THEN RETURN jsonb_build_object('result','invalid_rule');END IF;v_clarification:=trim(COALESCE(p_clarification_content,''));IF v_clarification='' OR char_length(v_clarification)>1200 OR v_clarification='__THINKING__' THEN RETURN jsonb_build_object('result','invalid_input','reason','clarification_content_invalid');END IF;v_reason:=trim(COALESCE(p_reason_code,''));IF v_reason='' OR char_length(v_reason)>200 THEN RETURN jsonb_build_object('result','invalid_input','reason','reason_code_invalid');END IF;SELECT id,status,assigned_agent_id INTO v_conv FROM public.conversations WHERE id=p_conversation_id FOR UPDATE;IF NOT FOUND THEN RETURN jsonb_build_object('result','not_found');END IF;IF v_conv.status IN ('resolved','closed') THEN RETURN jsonb_build_object('result','already_resolved');END IF;IF v_conv.status='transferred' OR (v_conv.status='pending' AND v_conv.assigned_agent_id IS NOT NULL) OR v_conv.assigned_agent_id IS NOT NULL THEN RETURN jsonb_build_object('result','already_under_human_control');END IF;IF NOT EXISTS(SELECT 1 FROM public.messages WHERE id=p_source_message_id AND conversation_id=p_conversation_id AND role='visitor' AND (is_recalled IS NULL OR is_recalled=false)) THEN RETURN jsonb_build_object('result','invalid_source_message');END IF;SELECT id INTO v_existing FROM public.messages WHERE conversation_id=p_conversation_id AND role='assistant' AND COALESCE(is_recalled,false)=false AND metadata->>'source_message_id'=p_source_message_id::text AND metadata->>'escalation_rule'='R2' AND metadata->>'escalation_action'='clarification' ORDER BY created_at ASC LIMIT 1;IF FOUND THEN RETURN jsonb_build_object('result','already_handled','message_id',v_existing.id);END IF;SELECT count(*) INTO v_prior_count FROM public.messages WHERE conversation_id=p_conversation_id AND role='assistant' AND COALESCE(is_recalled,false)=false AND metadata->>'escalation_rule'='R2' AND metadata->>'escalation_action'='clarification';IF v_prior_count>=1 THEN RETURN jsonb_build_object('result','max_clarifications_reached','clarification_attempts',v_prior_count);END IF;INSERT INTO public.messages(conversation_id,role,content,status,is_recalled,metadata) VALUES(p_conversation_id,'assistant',v_clarification,'delivered',false,jsonb_build_object('source_message_id',p_source_message_id::text,'escalation_rule','R2','escalation_action','clarification','reason_code',v_reason)) RETURNING id INTO v_message_id;UPDATE public.conversations SET updated_at=now() WHERE id=p_conversation_id;INSERT INTO public.audit_log(actor_id,actor_type,action,resource_type,resource_id,diff) VALUES(NULL,'ai','required_escalation_clarification','message',v_message_id,jsonb_build_object('conversation_id',p_conversation_id,'source_message_id',p_source_message_id,'escalation_rule','R2','reason_code',v_reason,'clarification_attempt',1));RETURN jsonb_build_object('result','success','message_id',v_message_id,'escalation_rule','R2','clarification_attempt',1);END;$function$
;
REVOKE ALL ON FUNCTION public.required_escalation_clarification_tx(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.required_escalation_clarification_tx(uuid,uuid,text,text,text) TO service_role;
